import { useCallback, useEffect, useRef, useState } from 'react'

// Only metadata changes here. Explicit snapshots are never regenerated by SSE.
export function useSnapshotFreshness(topics) {
  const key = topics.join(',')
  const revision = useRef(0)
  const scopeRevision = useRef(0)
  const generatedAt = useRef(0)
  const [stale, setStale] = useState(false)
  const [scopeVersion, setScopeVersion] = useState(0)
  useEffect(() => {
    const handler = event => {
      if (event.detail?.topics?.includes('scope')) setScopeVersion(++scopeRevision.current)
      if (event.detail?.resync || event.detail?.topics?.some(topic => key.split(',').includes(topic))) {
        revision.current++
        setStale(true)
      }
    }
    const returned = () => {
      if (document.visibilityState === 'visible') { revision.current++; setStale(true) }
    }
    window.addEventListener('sse:data_changed', handler)
    document.addEventListener('visibilitychange', returned)
    const timer = window.setInterval(() => {
      if (generatedAt.current && document.visibilityState === 'visible' && Date.now() - generatedAt.current >= 30_000) {
        revision.current++
        setStale(true)
      }
    }, 30_000)
    return () => {
      window.removeEventListener('sse:data_changed', handler)
      document.removeEventListener('visibilitychange', returned)
      window.clearInterval(timer)
    }
  }, [key])
  const begin = useCallback(() => revision.current, [])
  const complete = useCallback(start => {
    generatedAt.current = Date.now()
    setStale(start !== revision.current)
  }, [])
  const scopeCurrent = useCallback(version => version === scopeRevision.current, [])
  return { stale, begin, complete, scopeVersion, scopeCurrent }
}
